titleedit/blob/main/LICENSE","https://subtitleedit.github.io/subtitleedit/","https://github.com/SubtitleEdit/subtitleedit/releases"],"reviewNotes":{"basis":"Official repository metadata, README, license file, and referenced product documentation. The applications were not installed or executed.","installation":"Current README documents self-contained Windows/macOS builds and Linux Flatpak/native packages; official docs cover version 5.","license":"Official LICENSE file and recognized MIT metadata were inspected; bundled components may retain separate notices.","maintainedRepository":{"archived":false,"fork":false,"isTemplate":false,"pushedAt":"2026-11-02T06:14:57Z"},"evidence":{"readmePath":"README.md","readmeSha":"ce4d9c11326771cdf02e9944decd27e66d98e48e","licensePath":"LICENSE","licenseSha":"b46bc579feac40acca5046bc48a00fbcb74ecb44"},"baselineMatches":[]},"legacyUrls":[],"identityKeys":["url:subtitleedit.github.io/subtitleedit","repo:subtitleedit/subtitleedit","github-id:16473585"],"normalizedUrl":"subtitleedit.github.io/subtitleedit","repoKey":"github.com/subtitleedit/subtitleedit","iconUrl":"https://www.google.com/s2/favicons?domain=subtitleedit.github.io&sz=64","tagRecords":[{"name":"subtitles","slug":"subtitles"},{"name":"video-editing","slug":"video-editing"},{"name":"captioning","slug":"captioning"},{"name":"desktop","slug":"desktop"}]},{"name":"CherryTree","slug":"cherrytree","tagline":"Organize rich-text notes and code in a local tree","description":"CherryTree organizes notes in a hierarchy with rich text, syntax-highlighted code boxes, images, tables, and file attachments. It stores a notebook in a local XML or SQLite file, or in a directory-based format. Search, node links, and import/export features help manage technical references and larger personal notebooks.","url":"https://www.giuspen.net/cherrytree/","categorySlug":"writing-notes","platforms":["Linux","Windows"],"tags":["hierarchical-notes","rich-text","knowledge-management","offline"],"useCases":["Keep technical notes with formatted code examples","Organize a personal knowledge base in a hierarchy","Store reference documents and attachments locally"],"github":"https://github.com/giuspen/cherrytree","repositoryId":"32698469","licenseSpdxId":"GPL-3.0-or-later","reviewedAt":"2026-11-02","pricing":"OPEN_SOURCE","isOpenSource":true,"githubStars":3988,"githubStarsObservedAt":"2026-11-02T09:45:49.822569+00:00","pushedAt":"2026-11-01T22:28:58Z","defaultBranch":"master","sources":["https://github.com/giuspen/cherrytree","https://github.com/giuspen/cherrytree/blob/master/README.md","https://github.com/giuspen/cherrytree/blob/master/license.txt","https://www.giuspen.net/cherrytree/"],"reviewNotes":{"installation":"README links prebuilt releases and the official download page; build instructions are provided separately.","licenseScope":"GitHub metadata says NOASSERTION, but license.txt explicitly grants GPL version 3 or later; manually verified.","selectionReason":"Mature desktop knowledge tool with a different workflow from Markdown-only editors.","limitations":"Listed Windows and Linux platforms reflect documented distribution routes; no claim of having tested the packages.","reviewMethod":"Official repository metadata, README and actual license text. Upstream applications were not installed or executed."},"repositoryEvidence":{"archived":false,"fork":false,"disabled":false,"isTemplate":false,"readmeSha":"9684274a357f23895ea32a4588eb8c780d49c2be","licenseSha":"1977c0e21f7b4b85562b91726ffaa35ab8cfbd23","metadataLicenseSpdxId":"NOASSERTION"},"legacyUrls":[],"identityKeys":["url:giuspen.net/cherrytree","repo:giuspen/cherrytree","github-id:32698469"],"normalizedUrl":"giuspen.net/cherrytree","repoKey":"github.com/giuspen/cherrytree","iconUrl":"https://www.google.com/s2/favicons?domain=www.giuspen.net&sz=64","tagRecords":[{"name":"hierarchical-notes","slug":"hierarchical-notes"},{"name":"rich-text","slug":"rich-text"},{"name":"knowledge-management","slug":"knowledge-management"},{"name":"offline","slug":"offline"}]},{"name":"Markor","slug":"markor","tagline":"Edit Markdown notes and plain-text tasks on Android","description":"Markor is an Android text editor for local Markdown, todo.txt, and other plain-text files. It provides formatting helpers, previews, quick notes, and task editing while keeping documents in ordinary filesystem folders. It works offline; synchronizing those folders across devices is handled by a separate sync application.","url":"https://github.com/gsantner/markor","categorySlug":"writing-notes","platforms":["Android"],"tags":["markdown","offline-notes","todo-txt","android"],"useCases":["Write and preview Markdown notes on Android","Maintain todo.txt lists in portable text files","Edit documents that remain usable in other text editors"],"github":"https://github.com/gsantner/markor","repositoryId":"101451042","licenseSpdxId":"Apache-2.0","reviewedAt":"2026-11-02","pricing":"OPEN_SOURCE","isOpenSource":true,"githubStars":6366,"githubStarsObservedAt":"2026-11-02T09:45:49.822573+00:00","pushedAt":"2026-10-30T13:31:51Z","defaultBranch":"master","sources":["https://github.com/gsantner/markor","https://github.com/gsantner/markor/blob/master/README.md","https://github.com/gsantner/markor/blob/master/LICENSE.txt"],"reviewNotes":{"installation":"README links F-Droid and official GitHub release downloads.","licenseScope":"Actual LICENSE.txt and README identify Apache 2.0 for app code; translations and samples are CC0. GitHub NOASSERTION is not used as an open-source inference.","selectionReason":"Established mobile companion to portable Markdown and plaintext workflows.","limitations":"Android app; synchronization is not built into the editor.","reviewMethod":"Official repository metadata, README and actual license text. Upstream applications were not installed or executed."},"repositoryEvidence":{"archived":false,"fork":false,"disabled":false,"isTemplate":false,"readmeSha":"7e9a087689bf658c454cb2452d0889ef5d257532","licenseSha":"c0e1d9f80bd1cb936c50b0a3cfcf403332901a65","metadataLicenseSpdxId":"NOASSERTION"},"legacyUrls":[],"identityKeys":["url:github.com/gsantner/markor","repo:gsantner/markor","github-id:101451042"],"normalizedUrl":"github.com/gsantner/markor","repoKey":"github.com/gsantner/markor","iconUrl":"https://www.google.com/s2/favicons?domain=github.com&sz=64","tagRecords":[{"name":"markdown","slug":"markdown"},{"name":"offline-notes","slug":"offline-notes"},{"name":"todo-txt","slug":"todo-txt"},{"name":"android","slug":"android"}]}]'::jsonb) LOOP
    SELECT id INTO category_id FROM "Category" WHERE slug = candidate->>'categorySlug';
    IF category_id IS NULL THEN RAISE EXCEPTION 'Required reviewed category is missing'; END IF;
    incoming_keys := ARRAY(SELECT jsonb_array_elements_text(candidate->'identityKeys'));
    legacy_urls := ARRAY(SELECT jsonb_array_elements_text(candidate->'legacyUrls'));
    SELECT array_agg(DISTINCT t.id) INTO matching_ids FROM "Tool" t
    WHERE t.id IN (SELECT "toolId" FROM "ToolIdentity" WHERE key = ANY(incoming_keys))
      OR t.url = ANY(legacy_urls)
      OR lower(regexp_replace(regexp_replace(regexp_replace(t.github, '^https?://(www\.)?', '', 'i'), '[?#].*$', ''), '(\.git)?/+$|\.git$', '')) = candidate->>'repoKey'
      OR lower(regexp_replace(regexp_replace(regexp_replace(t.url, '^https?://(www\.)?', '', 'i'), '[?#].*$', ''), '(\.git)?/+$|\.git$', '')) = candidate->>'repoKey'
      OR (lower(substring(t.url from '(?i)^https?://(?:www\.)?([^/?#]+)')) || rtrim(coalesce(substring(t.url from '(?i)^https?://[^/?#]+([^?#]*)'), ''), '/') || coalesce(substring(split_part(t.url, '#', 1) from '\?.*$'), '')) = candidate->>'normalizedUrl';
    IF coalesce(cardinality(matching_ids), 0) > 1 THEN
      RAISE EXCEPTION 'Identity conflict for %: multiple existing listings', candidate->>'slug';
    END IF;
    tool_id := matching_ids[1];
    IF EXISTS (SELECT 1 FROM "Tool" WHERE slug = candidate->>'slug' AND id IS DISTINCT FROM tool_id) THEN
      RAISE EXCEPTION 'Slug conflict for %: belongs to another listing', candidate->>'slug';
    END IF;

    IF tool_id IS NOT NULL THEN
      SELECT * INTO STRICT tool_row FROM "Tool" WHERE id = tool_id FOR UPDATE;
      IF EXISTS (SELECT 1 FROM "ToolIdentity" WHERE "toolId" = tool_id
          AND key LIKE 'github-id:%' AND key <> 'github-id:' || (candidate->>'repositoryId'))
        OR (tool_row.github IS NOT NULL AND lower(regexp_replace(regexp_replace(regexp_replace(tool_row.github, '^https?://(www\.)?', '', 'i'), '[?#].*$', ''), '(\.git)?/+$|\.git$', '')) <> candidate->>'repoKey'
          AND NOT EXISTS (SELECT 1 FROM "ToolIdentity" WHERE "toolId" = tool_id AND key = 'github-id:' || (candidate->>'repositoryId')))
        OR (EXISTS (SELECT 1 FROM "ToolIdentity" WHERE "toolId" = tool_id AND key LIKE 'repo:%'
            AND key <> 'repo:' || regexp_replace(candidate->>'repoKey', '^github.com/', ''))
          AND NOT EXISTS (SELECT 1 FROM "ToolIdentity" WHERE "toolId" = tool_id AND key = 'github-id:' || (candidate->>'repositoryId'))) THEN
        RAISE EXCEPTION 'Repository conflict for %: review before merging', candidate->>'slug';
      END IF;
      -- The reviewed batch does not override an earlier moderation rejection.
      IF tool_row.status IN ('REJECTED', 'APPROVED') THEN CONTINUE; END IF;
      SELECT array_agg(item ORDER BY first_position) INTO use_cases FROM (
        SELECT item, min(position) AS first_position
        FROM unnest(coalesce(tool_row."useCases", ARRAY[]::text[]) || ARRAY(SELECT jsonb_array_elements_text(candidate->'useCases')))
          WITH ORDINALITY AS items(item, position) GROUP BY item
      ) merged;
      UPDATE "Tool" SET "categoryId" = category_id,
        name = candidate->>'name', tagline = candidate->>'tagline', description = candidate->>'description',
        platforms = ARRAY(SELECT jsonb_array_elements_text(candidate->'platforms')),
        "githubStars" = (candidate->>'githubStars')::integer,
        url = CASE WHEN status = 'PENDING' AND url = ANY(legacy_urls) THEN candidate->>'url' ELSE url END,
        github = coalesce(github, candidate->>'github'), status = 'APPROVED',
        pricing = CASE WHEN status = 'PENDING' THEN (candidate->>'pricing')::"Pricing" ELSE pricing END,
        "isOpenSource" = CASE WHEN status = 'PENDING' THEN (candidate->>'isOpenSource')::boolean ELSE "isOpenSource" END,
        "useCases" = use_cases,
        source = coalesce(source, 'GITHUB_REPOSITORY'::"ToolSource"),
        "sourceUrl" = CASE WHEN source IS NULL THEN candidate->>'github' ELSE "sourceUrl" END,
        "updatedAt" = now()
      WHERE id = tool_id AND (
        "categoryId" IS DISTINCT FROM category_id OR github IS NULL OR status <> 'APPROVED'
        OR "useCases" IS DISTINCT FROM use_cases OR source IS NULL
      );
    ELSE
      tool_id := gen_random_uuid()::text;
      INSERT INTO "Tool" (id, name, slug, tagline, description, url, "iconUrl", "categoryId", github,
        pricing, "isOpenSource", platforms, status, source, "sourceUrl", "useCases", "githubStars", "updatedAt")
      VALUES (tool_id, candidate->>'name', candidate->>'slug', candidate->>'tagline', candidate->>'description',
        candidate->>'url', candidate->>'iconUrl', category_id, candidate->>'github',
        (candidate->>'pricing')::"Pricing", (candidate->>'isOpenSource')::boolean,
        ARRAY(SELECT jsonb_array_elements_text(coalesce(candidate->'platforms', '[]'::jsonb))),
        'APPROVED', 'GITHUB_REPOSITORY', candidate->>'github',
        ARRAY(SELECT jsonb_array_elements_text(candidate->'useCases')), (candidate->>'githubStars')::integer, now());
    END IF;

    INSERT INTO "ToolIdentity" (key, "toolId") SELECT unnest(incoming_keys), tool_id
      ON CONFLICT (key) DO NOTHING;
    IF EXISTS (SELECT 1 FROM "ToolIdentity" WHERE key = ANY(incoming_keys) AND "toolId" <> tool_id) THEN
      RAISE EXCEPTION 'Identity claim conflict for %', candidate->>'slug';
    END IF;
    FOR tag IN SELECT value FROM jsonb_array_elements(candidate->'tagRecords') LOOP
      INSERT INTO "Tag" (id, name, slug)
        SELECT gen_random_uuid()::text, tag->>'name', tag->>'slug'
        WHERE NOT EXISTS (SELECT 1 FROM "Tag" WHERE slug = tag->>'slug' OR lower(name) = lower(tag->>'name'));
      INSERT INTO "ToolTag" ("toolId", "tagId")
        SELECT tool_id, id FROM "Tag" WHERE slug = tag->>'slug' OR lower(name) = lower(tag->>'name')
        ORDER BY (slug = tag->>'slug') DESC LIMIT 1 ON CONFLICT DO NOTHING;
    END LOOP;
    INSERT INTO "ToolDiscovery" (id, "toolId", source, method, "sourceKey", "sourceUrl", metadata)
      VALUES (gen_random_uuid()::text, tool_id, 'GITHUB_REPOSITORY', 'editorial-review',
        'github-reviewed-2026-11-02:' || (candidate->>'repoKey'), candidate->>'github',
        jsonb_build_object('reviewedAt', candidate->>'reviewedAt', 'reviewBasis', 'official public documentation',
          'sources', candidate->'sources', 'repositoryId', candidate->>'repositoryId',
          'licenseSpdxId', candidate->>'licenseSpdxId', 'legacyUrls', candidate->'legacyUrls', 'category', candidate->>'categorySlug',
          'githubStars', candidate->'githubStars', 'observedOn', candidate->>'reviewedAt',
          'defaultBranch', candidate->>'defaultBranch', 'pushedAt', candidate->>'pushedAt',
          'reviewNotes', candidate->'reviewNotes', 'batch', 'github-reviewed-2026-11-02'))
      ON CONFLICT ("toolId", source, method, "sourceKey") DO UPDATE SET
        "sourceUrl" = EXCLUDED."sourceUrl", metadata = EXCLUDED.metadata, "lastSeenAt" = now();
  END LOOP;

END
$toools_curation$;
COMMIT;
